{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']

    # Build mutual reachability edges
    edges = []
    for u, v, d in dists:
        # canonical order
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    # Sort: weight, then u, then v
    edges.sort()

    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target = len(nodes) - 1

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == target:
                break

    # If disconnected, still return what we have (should not happen per spec)
    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
